import app from 'flarum/admin/app';
import { extend } from 'flarum/common/extend';
import Stream from 'flarum/common/utils/Stream';
import Group from 'flarum/common/models/Group';
import { expertGroupIds, t } from '../common/utils/experts';
export { default as extend } from './extend';
const MODAL = 'ext:flarum/tags/admin/components/EditTagModal';
app.initializers.add('ramon-tag-experts', () => {
  extend(MODAL, 'oninit', function () {
    this.tagExpertGroups = Stream(this.tag.exists ? expertGroupIds(this.tag) : []);
    this.tagExpertEndorsements = Stream(!!this.tag.attribute('acceptsExpertEndorsements'));
  });

  // Logo antes da ordenação padrão, junto das outras opções da tag.
  extend(MODAL, 'fields', function (items) {
    // Os mesmos que o servidor aceita: Visitantes e Membros seriam todo mundo,
    // Admins e Mods dariam poder de equipe a quem for aprovado, e o selo
    // revelaria quem está num grupo oculto. O JS do core não tem a constante
    // dos Mods (4).
    const ineligible = [Group.ADMINISTRATOR_ID, Group.GUEST_ID, Group.MEMBER_ID, '4'];
    const groups = app.store.all('groups').filter(group => !ineligible.includes(group.id()) && !group.isHidden());
    const selected = this.tagExpertGroups();
    const toggle = (id, checked) => {
      this.tagExpertGroups(checked ? [...selected, id] : selected.filter(item => item !== id));
    };
    items.add('tagExpertGroups', m("div", {
      className: "Form-group TagExpertGroups"
    }, m("label", null, t('admin.edit_tag.expert_groups_label')), m("div", {
      className: "helpText"
    }, t('admin.edit_tag.expert_groups_help')), groups.map(group => m("label", {
      className: "checkbox",
      key: group.id()
    }, m("input", {
      type: "checkbox",
      checked: selected.includes(group.id()),
      onchange: e => toggle(group.id(), e.target.checked)
    }), group.namePlural()))), 7);
    items.add('tagExpertEndorsements', m("div", {
      className: "Form-group"
    }, m("label", {
      className: "checkbox"
    }, m("input", {
      type: "checkbox",
      bidi: this.tagExpertEndorsements
    }), t('admin.edit_tag.accepts_recommendations_label'))), 6);
  });
  extend(MODAL, 'submitData', function (data) {
    data.expertGroupIds = this.tagExpertGroups().map(Number);
    data.acceptsExpertEndorsements = this.tagExpertEndorsements();
  });
});